import * as React from 'react'
import { formatCentsToEuro } from '@/shared/lib/utils.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CurrencyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value'> {
  /** Current value in cents (integer) */
  value: number
  /** Change callback — receives new value in cents */
  onChange: (cents: number) => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * CurrencyInput — accepts decimal euros, converts to/from cents.
 *
 * Displays values as €X.XX but stores them internally as integer cents.
 * This prevents floating-point precision issues while providing a familiar
 * euro-formatted display for users.
 */
export function CurrencyInput({ value, onChange, className, ...props }: CurrencyInputProps) {
  const [displayValue, setDisplayValue] = React.useState(formatCentsToEuro(value))

  // Update display when cents change externally
  React.useEffect(() => {
    setDisplayValue(formatCentsToEuro(value))
  }, [value])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value

    // Allow empty input during typing
    if (raw === '' || raw === '-') {
      onChange(0)
      return
    }

    // Parse decimal euros → cents
    const euroValue = parseFloat(raw.replace(',', '.'))
    if (isNaN(euroValue) || euroValue < 0) {
      return
    }

    const cents = Math.round(euroValue * 100)
    onChange(cents)
  }

  const handleBlur = () => {
    // Format to 2 decimal places on blur
    setDisplayValue(formatCentsToEuro(value))
  }

  return (
    <div className="relative">
      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">€</span>
      <input
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleChange}
        onBlur={handleBlur}
        className={`h-10 w-full rounded-md border border-input bg-background pl-7 pr-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 ${className ?? ''}`}
        {...props}
      />
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** Generate a unique ID for optimistic UI updates.
 * Works in both browser and Node.js without crypto.randomUUID(). */
export function generateId(): string {
  return Math.random().toString(36).substring(2) + Date.now().toString(36)
}

/** Format cents (integer) to Euro string with 2 decimal places. */
export function formatCentsToEuro(cents: number): string {
  return `€${(cents / 100).toFixed(2)}`
}

import * as React from 'react'
import { describe, it, expect, vi } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { CurrencyInput } from '../CurrencyInput.js'

describe('CurrencyInput', () => {
  it('should display €12.50 when value is 1250 cents', () => {
    render(<CurrencyInput value={1250} onChange={() => {}} />)
    expect(screen.getByDisplayValue('€12.50')).toBeInTheDocument()
  })

  it('should display €0.00 when value is 0', () => {
    render(<CurrencyInput value={0} onChange={() => {}} />)
    expect(screen.getByDisplayValue('€0.00')).toBeInTheDocument()
  })

  it('should call onChange with cents when user types decimal euros', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={0} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '25.50' } })

    expect(handleChange).toHaveBeenCalledWith(2550)
  })

  it('should handle comma as decimal separator', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={0} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '12,50' } })

    expect(handleChange).toHaveBeenCalledWith(1250)
  })

  it('should format back to €X.XX on blur', () => {
    // Use a stateful wrapper to simulate parent updating value
    function TestWrapper() {
      const [cents, setCents] = React.useState(999)
      return <CurrencyInput value={cents} onChange={setCents} />
    }
    render(<TestWrapper />)

    const input = screen.getByRole('textbox')
    // Initial display should be formatted
    expect((input as HTMLInputElement).value).toBe('€9.99')

    fireEvent.blur(input)
    // After blur, value stays the same (already formatted)
    expect((input as HTMLInputElement).value).toBe('€9.99')
  })

  it('should reject negative values', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={0} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '-5' } })

    expect(handleChange).not.toHaveBeenCalled()
  })

  it('should handle empty input', () => {
    const handleChange = vi.fn()
    render(<CurrencyInput value={100} onChange={handleChange} />)

    const input = screen.getByRole('textbox')
    fireEvent.change(input, { target: { value: '' } })

    expect(handleChange).toHaveBeenCalledWith(0)
  })
})
